      ]
    },
    {
      "id": "I1-03",
      "ja": "ニセモノなんか興味はないの",
      "budget": {
        "min": 12,
        "max": 12
      },
      "pattern": [
        6,
        6
      ]
    },
    {
      "id": "I1-04",
      "ja": "ホントだけを見つめたい",
      "budget": {
        "min": 11,
        "max": 11
      },
      "pattern": [
        6,
        5
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "I1-01",
          "zh": "爱从何来 又往哪去 住进谁的胸口"
        },
        {
          "id": "I1-02",
          "zh": "手贴胸口 轻轻问 心是否诚实"
        },
        {
          "id": "I1-03",
          "zh": "假货摆得再亮 我也只要真的"
        },
        {
          "id": "I1-04",
          "zh": "只想看清真实 眼神不闪躲"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "I1-01",
          "zh": "爱从何处 降临人间 无声却很明亮"
        },
        {
          "id": "I1-02",
          "zh": "按着胸口 问自己 听心跳回答"
        },
        {
          "id": "I1-03",
          "zh": "橱窗里的假货 我一眼都不看"
        },
        {
          "id": "I1-04",
          "zh": "我只想要握住 真正的重量"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "I1-01",
          "zh": "爱究竟从何处悄悄降临人间"
        },
        {
          "id": "I1-02",
          "zh": "我轻声问自己心间"
        },
        {
          "id": "I1-03",
          "zh": "虚假的温柔我从来不愿多看一眼"
        },
        {
          "id": "I1-04",
          "zh": "只想凝视那份真实的脸"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "I1-01",
          "zh": "爱究竟是从何处降临的呢"
        },
        {
          "id": "I1-02",
          "zh": "我向自己的胸膛发问"
        },
        {
          "id": "I1-03",
          "zh": "虚假的东西我毫无兴趣"
        },
        {
          "id": "I1-04",
          "zh": "只想凝视真实的一切"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "I1-01",
          "zh": "爱情究竟是从什么地方飘来的哦"
        },
        {
          "id": "I1-02",
          "zh": "我向自己的内心深处去坦白"
        },
        {
          "id": "I1-03",
          "zh": "对虚假的东西我毫无兴趣哦"
        },
        {
          "id": "I1-04",
          "zh": "我只想凝视着那一份真爱"
        }
      ]
    }
  ]
}

